        apertures = {c: [r for r in range(h) if g[r][c] != 8] for c in walls}
        first = walls[0]
        if apertures[first]:
            rr = first - 1
            for r in range(min([mr] + apertures[first]), max([mr] + apertures[first]) + 1):
                if out[r][rr] == 0:
                    out[r][rr] = 2
        for c in walls:
            for r in apertures[c]:
                if out[r][c] == 0:
                    out[r][c] = 2
        for i, c in enumerate(walls[:-1]):
            nxt = walls[i + 1]
            gap_count = nxt - c - 1
            upper, lower = apertures[c], apertures[nxt]
            for r in upper:
                for cc in range(c + 1, nxt):
                    if out[r][cc] == 0:
                        out[r][cc] = 2
            if gap_count == 1 and lower:
                rr = nxt - 1
                for r in range(min(lower), max(lower) + 1):
                    if out[r][rr] == 0:
                        out[r][rr] = 2
            elif gap_count > 1:
                for r in range(h):
                    if out[r][nxt - 1] == 0:
                        out[r][nxt - 1] = 2
        last = walls[-1]
        for r in apertures[last]:
            for cc in range(last + 1, w):
                if out[r][cc] == 0:
                    out[r][cc] = 2
    return out
