 "content": "def _select_gaps(active, gaps):
    """Take the closest opening on either side of each incoming lane."""
    chosen = set()
    for x in active:
        left = [g for g in gaps if g < x]
        right = [g for g in gaps if g > x]
        if x in gaps:
            chosen.add(x)
        else:
            if left:
                chosen.add(left[-1])
            if right:
                chosen.add(right[0])
    return sorted(chosen)


def _trace(grid, horizontal):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marker = next(((r, c) for r in range(h) for c in range(w) if grid[r][c] == 2), None)
    if marker is None:
        return out
    mr, mc = marker
    if horizontal:
        walls = [r for r in range(h) if sum(v == 8 for v in grid[r]) >= max(2, w // 2)]
        walls = [r for r in walls if r > mr]
        if not walls:
            return out
        active = [mc]
        previous = mr
        for wi, r in enumerate(walls):
            gaps = [c for c, v in enumerate(grid[r]) if v != 8]
            selected = _select_gaps(active, gaps)
            if not selected:
                return out
            # Route toward selected gaps along the row immediately above wall.
            approach = r - 1
            if approach >= 0:
                if wi == 0:
                    lo, hi = min(active + selected), max(active + selected)
                    for c in range(lo, hi + 1):
                        if out[approach][c] == 0:
                            out[approach][c] = 2
                else:
                    for c in range(min(selected), max(selected) + 1):
                        if out[approach][c] == 0:
                            out[approach][c] = 2
            for c in selected:
                if out[r][c] == 0:
                    out[r][c] = 2
            if wi == len(walls) - 1:
                for c in selected:
                    for rr in range(r + 1, h):
                        if out[rr][c] == 0:
                            out[rr][c] = 2
                break
            nxt = walls[wi + 1]
            distance = nxt - r - 1
            if distance == 1:
                # Carry the incoming lanes through the open row to the next wall.
                for c in selected:
                    if out[r + 1][c] == 0:
                        out[r + 1][c] = 2
            elif distance >= 2:
                # Continue along each lane, then join through the open chamber
                # immediately before the next barrier.
                for c in selected:
                    for rr in range(r + 1, nxt - 1):
                        if out[rr][c] == 0:
                            out[rr][c] = 2
                for c in range(w):
                    if out[nxt - 1][c] == 0:
                        out[nxt - 1][c] = 2
            active = selected
            previous = r
        return out

    # Transposed version for vertical stripe barriers.
    walls = [c for c in range(w) if sum(grid[r][c] == 8 for r in range(h)) >= max(2, h // 2)]
    walls = [c for c in walls if c > mc]
    if not walls:
        return out
    active = [mr]
    for wi, c in enumerate(walls):
        gaps = [r for r in range(h) if grid[r][c] != 8]
        selected = _select_gaps(active, gaps)
        if not selected:
            return out
        approach = c - 1
        if approach >= 0:
            if wi == 0:
                lo, hi = min(active + selected), max(active + selected)
                for r in range(lo, hi + 1):
                    if out[r][approach] == 0:
                        out[r][approach] = 2
            else:
                for r in range(min(selected), max(selected) + 1):
                    if out[r][approach] == 0:
                        out[r][approach] = 2
        for r in selected:
            if out[r][c] == 0:
                out[r][c] = 2
        if wi == len(walls) - 1:
            for r in selected:
                for cc in range(c + 1, w):
                    if out[r][cc] == 0:
                        out[r][cc] = 2
            break
        nxt = walls[wi + 1]
        distance = nxt - c - 1
        if distance == 1:
            for r in selected:
                if out[r][c + 1] == 0:
                    out[r][c + 1] = 2
        elif distance >= 2:
            for r in selected:
                for cc in range(c + 1, nxt - 1):
                    if out[r][cc] == 0:
                        out[r][cc] = 2
            for r in range(h):
                if out[r][nxt - 1] == 0:
                    out[r][nxt - 1] = 2
        active = selected
    return out


def transform(grid):
    """Trace the colored marker through the nearest openings in 8-stripes."""
    h, w = len(grid), len(grid[0])
    # Orient the repeated barriers by which axis contains the stronger stripes.
    row_strength = max((sum(v == 8 for v in row) for row in grid), default=0)
    col_strength = max((sum(grid[r][c] == 8 for r in range(h)) for c in range(w)), default=0)
    return _trace(grid, horizontal=row_strength >= col_strength)


if __name__ == "__main__":
