 "content": "def _nearest_gaps(active, gaps):
    """Select every gap that is nearest on either side of an incoming lane."""
    chosen = set()
    for x in active:
        left = [g for g in gaps if g < x]
        right = [g for g in gaps if g > x]
        if x in gaps:
            chosen.add(x)
        else:
            if left:
                chosen.add(left[-1])
            if right:
                chosen.add(right[0])
    return sorted(chosen)


def _trace_axis(a, marker_axis, marker_cross):
    """Trace color 2 through repeated 8-barriers in an oriented matrix."""
    n, m = len(a), len(a[0])
    out = [row[:] for row in a]
    walls = [i for i in range(n) if sum(v == 8 for v in a[i]) >= max(2, m // 2)]
    if not walls:
        return out

    above = [i for i in walls if i < marker_axis]
    below = [i for i in walls if i > marker_axis]
    if below and (not above or min(below) - marker_axis <= marker_axis - max(above)):
        direction = 1
        ordered = sorted(below)
    elif above:
        direction = -1
        ordered = sorted(above, reverse=True)
    else:
        return out

    active = [marker_cross]
    prev = None
    for wi, wall in enumerate(ordered):
        gaps = [j for j, v in enumerate(a[wall]) if v != 8]
        selected = _nearest_gaps(active, gaps)
        if not selected:
            return out

        if wi == 0:
            approach = wall - direction
            lo, hi = min(active + selected), max(active + selected)
            if 0 <= approach < n:
                for j in range(lo, hi + 1):
                    if out[approach][j] == 0:
                        out[approach][j] = 2
        else:
            distance = abs(wall - prev)
            intermediate = list(range(prev + direction, wall, direction))
            if intermediate:
                approach = wall - direction
                for axis in intermediate:
                    if axis == approach:
                        lo, hi = min(active + selected), max(active + selected)
                        for j in range(lo, hi + 1):
                            if out[axis][j] == 0:
                                out[axis][j] = 2
                    else:
                        for j in active:
                            if out[axis][j] == 0:
                                out[axis][j] = 2

        for j in selected:
            if out[wall][j] == 0:
                out[wall][j] = 2
        active = selected
        prev = wall

    # Continue the final lanes to the edge beyond the last barrier.
    for axis in range(ordered[-1] + direction, n if direction > 0 else -1, direction):
        for j in active:
            if out[axis][j] == 0:
                out[axis][j] = 2
    return out


def transform(grid):
    """Color paths from the 2 marker through openings in repeated 8-stripes."""
    h, w = len(grid), len(grid[0])
    marker = next(((r, c) for r in range(h) for c in range(w) if grid[r][c] == 2), None)
    if marker is None:
        return [row[:] for row in grid]
    row_strength = max(sum(v == 8 for v in row) for row in grid)
    col_strength = max(sum(grid[r][c] == 8 for r in range(h)) for c in range(w))
    if row_strength >= col_strength:
        return _trace_axis([row[:] for row in grid], marker[0], marker[1])
    transposed = [[grid[r][c] for r in range(h)] for c in range(w)]
    traced = _trace_axis(transposed, marker[1], marker[0])
    return [[traced[c][r] for c in range(w)] for r in range(h)]


if __name__ == "__main__":
    pass
